class.description:
Nœud à placer comme enfant direct du corps à repousser. Mêmes règles qu'en 2D, axe Y vers le haut : [member upward_bias] soulève le corps, [method apply_knockback_from] repousse dans le plan horizontal et [member friction] ne freine que la vitesse horizontale.
[codeblock]
func exploser(centre: Vector3, rayon: float) -> void:
	for corps in get_tree().get_nodes_in_group("destructibles"):
		var recul := corps.get_node_or_null("Knockback3D") as Knockback3D
		var distance: float = corps.global_position.distance_to(centre)
		if recul and distance < rayon:
			recul.apply_knockback_from(centre, 1.0 - distance / rayon)
[/codeblock]
